// ── DFA Simulator ──────────────────────────────────────────────
// Accepts strings over {a,b} containing 'ab' as a substring.
// States: 0 = start (no progress)
//         1 = last symbol was 'a'
//         2 = 'ab' has been seen (accept)
const dfa = {
  start: 0,
  accept: new Set([2]),
  transitions: {
    0: { a: 1, b: 0 },
    1: { a: 1, b: 2 },
    2: { a: 2, b: 2 },
  },
};

function dfaRun(machine, input) {
  let state = machine.start;
  for (const ch of input) {
    const row = machine.transitions[state];
    if (!row || !(ch in row)) return false; // dead / undefined transition
    state = row[ch];
  }
  return machine.accept.has(state);
}

console.log(dfaRun(dfa, 'bab'));    // true  — 'bab' contains 'ab'
console.log(dfaRun(dfa, 'bbba'));   // false — no 'ab'
console.log(dfaRun(dfa, 'aab'));    // true
console.log(dfaRun(dfa, ''));       // false — empty string

// ── NFA Simulator (on-the-fly subset construction) ───────────────
// NFA accepting strings ending in 'abb'
// States: s0 (loop + branch), s1, s2, s3 (accept)
const nfa = {
  start: 's0',
  accept: new Set(['s3']),
  transitions: {
    s0: { a: ['s0', 's1'], b: ['s0'] },
    s1: { b: ['s2'] },
    s2: { b: ['s3'] },
    s3: {},
  },
};

function nfaRun(machine, input) {
  // 'current' is the set of all active NFA states (the DFA subset)
  let current = new Set([machine.start]);
  for (const ch of input) {
    const next = new Set();
    for (const state of current) {
      const targets = machine.transitions[state]?.[ch] ?? [];
      for (const t of targets) next.add(t);
    }
    current = next;
    if (current.size === 0) return false; // all paths died
  }
  // Accept if any active state is an accept state
  return [...current].some(s => machine.accept.has(s));
}

console.log(nfaRun(nfa, 'aabb'));   // true  — ends in 'abb'
console.log(nfaRun(nfa, 'abb'));    // true
console.log(nfaRun(nfa, 'ab'));     // false — only two suffix chars
console.log(nfaRun(nfa, 'abba'));   // false — ends in 'a' not 'bb'

// ── Thompson's construction: core NFA fragment builder ──────────
// We represent NFA states as objects with a 'transitions' map.
// Each fragment exposes { start, accept } as entry/exit points.

let stateId = 0;
function newState() {
  return { id: stateId++, transitions: {}, epsilon: [] };
}

// Atom: NFA for a single character 'ch'
function atomNFA(ch) {
  const start  = newState();
  const accept = newState();
  start.transitions[ch] = [accept];
  return { start, accept };
}

// Concatenation: NFA(r) followed by NFA(s)
function concatNFA(r, s) {
  r.accept.epsilon.push(s.start); // ε link r.accept -> s.start
  return { start: r.start, accept: s.accept };
}

// Union: NFA(r) | NFA(s)
function unionNFA(r, s) {
  const start  = newState();
  const accept = newState();
  start.epsilon.push(r.start, s.start);
  r.accept.epsilon.push(accept);
  s.accept.epsilon.push(accept);
  return { start, accept };
}

// Kleene star: NFA(r)*
function starNFA(r) {
  const start  = newState();
  const accept = newState();
  start.epsilon.push(r.start, accept);   // zero repetitions path
  r.accept.epsilon.push(r.start, accept); // loop back + exit
  return { start, accept };
}

// Example: build NFA for regex (a|b)*abb
// Step 1: (a|b)*
const aNFA   = atomNFA('a');
const bNFA   = atomNFA('b');
const abUnion = unionNFA(aNFA, bNFA);
const abStar  = starNFA(abUnion);
// Step 2: concatenate with 'abb'
const a2 = atomNFA('a');
const b2 = atomNFA('b');
const b3 = atomNFA('b');
const full = concatNFA(abStar, concatNFA(a2, concatNFA(b2, b3)));

console.log('NFA start state id:', full.start.id);
console.log('NFA accept state id:', full.accept.id);
console.log('Total states created:', stateId);
