// ── DFA product construction: intersection of two languages ─────
// L1: strings containing 'ab'   (DFA1, states 0,1,2)
// L2: strings of even length    (DFA2, states A,B)
// L1 ∩ L2: strings containing 'ab' AND having even length
//
// Product states: pairs (dfa1State, dfa2State)

const dfa1 = {
  start: 0, accept: new Set([2]),
  delta: { 0:{a:1,b:0}, 1:{a:1,b:2}, 2:{a:2,b:2} },
};

const dfa2 = {
  start: 'A', accept: new Set(['A']), // even length = back to A
  delta: { A:{a:'B',b:'B'}, B:{a:'A',b:'A'} },
};

function productRun(m1, m2, input) {
  let s1 = m1.start, s2 = m2.start;
  for (const ch of input) {
    s1 = m1.delta[s1]?.[ch];
    s2 = m2.delta[s2]?.[ch];
    if (s1 === undefined || s2 === undefined) return false;
  }
  // Accept only if BOTH DFAs are in accept states
  return m1.accept.has(s1) && m2.accept.has(s2);
}

console.log(productRun(dfa1, dfa2, 'ab'));    // true  — has 'ab', length 2 (even)
console.log(productRun(dfa1, dfa2, 'aab'));   // false — has 'ab', length 3 (odd)
console.log(productRun(dfa1, dfa2, 'bab'));   // false — has 'ab', length 3 (odd)
console.log(productRun(dfa1, dfa2, 'baab'));  // true  — has 'ab', length 4 (even)
console.log(productRun(dfa1, dfa2, 'bbbb'));  // false — no 'ab'

// ── Pumping Lemma demo: showing 'a^n b^n' is not regular ────────
// If it were regular with pumping length p, take w = a^p b^p.
// Any split w=xyz with |xy|<=p means y is entirely a's.
// Pumping y twice gives a^(p+|y|) b^p  — unequal counts → not in language.
// Contradiction. So {a^n b^n} is not regular.
function isBalancedAB(s) {
  // This requires COUNTING — impossible for a DFA
  let count = 0;
  for (const ch of s) {
    if (ch === 'a') count++;
    else if (ch === 'b') count--;
    else return false;
    if (count < 0) return false; // b before a
  }
  return count === 0;
}
console.log(isBalancedAB('aaabbb')); // true  — but no DFA can do this
